# November 19, 2026: Île d'Orléans and the Côte-de-Beaupré (Boischatel to Saint-Joachim), Quebec. Region qc drawn at
# random by tools/choose.py --claim --state qc,nb,ns,pe,nl. Sources opened in this session: the Canadian Register of
# Historic Places statement for each designated place (historicplaces.ca, read with tools/page.py --all; most Quebec
# statements are in French, from the Ministère de la Culture, and were read in French); Wikipedia as raw text
# (tools/wiki_raw.py: Maison Drouin, Moulin du Petit-Pré, Centre d'Interprétation de la Côte-de-Beaupré, and the
# "List of historic places in Capitale-Nationale" for Register ids and coordinates); the operators' own pages (Manoir
# Mauvide-Genest, the Musée maritime de l'Île d'Orléans, the Fondation François-Lamy for Maison Drouin, the Musée de La
# Grande Ferme); Bridgemeister on the 1856 Montmorency bridge. Church service times were not found on any parish page.
from data_b import N
from data_ma import W
def L(t,u): return [t,u]
def HP(t,i): return ['Canadian Register of Historic Places: '+t,'https://www.historicplaces.ca/en/rep-reg/place-lieu.aspx?id=%d'%i]
BATCH={'key':'qc_bpqv','label':"Île d'Orléans and the Côte-de-Beaupré, Quebec",'added':'2026-11-19 20:16'}
